<script setup lang="ts">
import { memoryActivityLabel, type MemoryActivityReport } from '../../../shared/memory-activity'
import { dialogFocus as vDialogFocus } from '../dialog-focus'
import AppIcon from './AppIcon.vue'
defineProps<{ report: MemoryActivityReport; loading?: boolean }>()
const emit = defineEmits<{ close: []; refresh: []; review: [] }>()
</script>
<template><div class="modal-backdrop" @pointerdown.self.prevent><section v-dialog-focus="() => emit('close')" class="chat-feature-dialog memory-activity-dialog" role="dialog" aria-modal="true" aria-label="记忆处理状态"><div class="dialog-header"><div><h2>记忆处理状态</h2><p>当前对话的后台任务与 L1 发布结果</p></div><button class="dialog-close" aria-label="关闭记忆状态" @click="emit('close')"><AppIcon name="close" /></button></div><div class="activity-totals"><span>等待<strong>{{ report.totals.pending }}</strong></span><span>处理<strong>{{ report.totals.processing }}</strong></span><span>待补充<strong>{{ report.totals.clarifying }}</strong></span><span>失败<strong>{{ report.totals.failed }}</strong></span><span>L1 已发布<strong>{{ report.totals.published }}</strong></span></div><p v-if="report.error" class="chat-feature-error">{{ report.error }}</p><p v-if="report.awaitingProcessor" class="chat-feature-hint">{{ report.awaitingProcessor }} 个任务等待对应的抽取配置。</p><div class="activity-list"><article v-for="item in report.items" :key="item.id" class="activity-item"><header><span :class="{ working: item.processing, warning: item.failed || item.clarifying }">{{ memoryActivityLabel(item) }}</span><small>{{ new Date(item.createdAt).toLocaleString('zh-CN') }}</small></header><p>{{ item.text || '原文暂不可用' }}</p><footer><span v-if="item.published">已发布 {{ item.published }} 条 L1 事实</span><span v-if="item.clarifying">{{ item.clarifying }} 项待补充</span><span v-if="item.completed && !item.published">整理完成，尚未发布 L1 事实</span></footer></article><p v-if="!report.items.length" class="chat-feature-empty">{{ report.enabled ? '当前对话还没有记忆任务。' : '当前未启用记忆处理。' }}</p></div><div class="settings-footer"><button class="secondary-btn" :disabled="loading" @click="emit('refresh')">{{ loading ? '刷新中…' : '刷新状态' }}</button><span /><button class="primary-btn" @click="emit('review')">打开记忆库</button></div></section></div></template>
